 1	// Config resolution tests — the 3-step precedence behind a no-`--config` run, and the
 2	// XDG-aware user config path. This is the P2 regression guard: a bare run on a foreign
 3	// machine must NOT auto-load the host-specific examples/debate.yaml; it must fall through
 4	// to the built-in lineup (text:null).
 5	
 6	import { test } from "node:test";
 7	import assert from "node:assert/strict";
 8	import { mkdtemp, mkdir, writeFile, rm } from "node:fs/promises";
 9	import { tmpdir } from "node:os";
10	import { join } from "node:path";
11	import { userConfigPath, resolveConfigText } from "../src/install.ts";
12	import { parseDebateConfig } from "../src/config.ts";
13	
14	test("userConfigPath honors XDG_CONFIG_HOME, else ~/.config", () => {
15	  assert.equal(
16	    userConfigPath({ XDG_CONFIG_HOME: "/x/cfg" }),
17	    join("/x/cfg", "disputatio", "config.yaml"),
18	  );
19	  const home = userConfigPath({ HOME: "<user-home>" } as NodeJS.ProcessEnv);
20	  assert.match(home, /[/\\]\.config[/\\]disputatio[/\\]config\.yaml$/);
21	});
22	
23	test("no --config + no user config → built-in lineup (text:null) — the P2 guard", async () => {
24	  const xdg = await mkdtemp(join(tmpdir(), "disputatio-xdg-"));
25	  try {
26	    const { text, source } = await resolveConfigText(undefined, { XDG_CONFIG_HOME: xdg });
27	    assert.equal(text, null); // → index.ts uses DEFAULT_SPECS, no /opt/homebrew assumption
28	    assert.match(source, /built-in/);
29	  } finally {
30	    await rm(xdg, { recursive: true, force: true });
31	  }
32	});
33	
34	test("no --config but user config present → loads it", async () => {
35	  const xdg = await mkdtemp(join(tmpdir(), "disputatio-xdg-"));
36	  try {
37	    await mkdir(join(xdg, "disputatio"), { recursive: true });
38	    await writeFile(join(xdg, "disputatio", "config.yaml"), "participants:\n  - adapter: claude\n  - adapter: codex\n");
39	    const { text, source } = await resolveConfigText(undefined, { XDG_CONFIG_HOME: xdg });
40	    assert.ok(text && text.includes("adapter: claude"));
41	    assert.equal(source, join(xdg, "disputatio", "config.yaml"));
42	    assert.equal(parseDebateConfig(text!).participants?.length, 2);
43	  } finally {
44	    await rm(xdg, { recursive: true, force: true });
45	  }
46	});
47	
48	test("explicit --config that does not exist → hard-fails (does not silently fall back)", async () => {
49	  await assert.rejects(() => resolveConfigText(join(tmpdir(), "does-not-exist-xyz.yaml"), {}));
50	});
51	
52	test("a malformed user config still surfaces (parse throws downstream, not swallowed)", async () => {
53	  const xdg = await mkdtemp(join(tmpdir(), "disputatio-xdg-"));
54	  try {
55	    await mkdir(join(xdg, "disputatio"), { recursive: true });
56	    await writeFile(join(xdg, "disputatio", "config.yaml"), "participants:\n  - adapter: bogus\n  - adapter: codex\n");
57	    const { text } = await resolveConfigText(undefined, { XDG_CONFIG_HOME: xdg });
58	    assert.ok(text !== null); // resolution returns the text...
59	    assert.throws(() => parseDebateConfig(text!)); // ...and the bad adapter fails at parse, not here
60	  } finally {
61	    await rm(xdg, { recursive: true, force: true });
62	  }
63	});

