  1	// Transport layer (Kaizen v0).
  2	// One job: spawn a real agent CLI, capture its output, classify success/failure.
  3	// Every rule here is grounded in research/canary-results.md (verified locally).
  4	// Written with node: APIs so it runs on Node 24 today and stays Bun-compatible.
  5	
  6	import { spawn } from "node:child_process";
  7	
  8	// Agents can think for minutes; cap wall-clock. 10m: a repo-grounded run showed
  9	// 5m is too tight for larger evidence-gathering turns.
 10	export const DEFAULT_TIMEOUT_MS = 10 * 60 * 1000;
 11	
 12	export type CliCapture = { code: number | null; stdout: string; stderr: string; timedOut: boolean };
 13	
 14	// After SIGTERM-ing a timed-out group, wait this long for a graceful exit, then
 15	// SIGKILL the whole group. A CLI that traps/ignores SIGTERM cannot outlive this.
 16	export const KILL_GRACE_MS = 2_000;
 17	
 18	// Spawn a CLI in `cwd`. stdin is IGNORED (= </dev/null): the canary showed Codex
 19	// hangs waiting for stdin EOF otherwise. stdout/stderr captured separately.
 20	//
 21	// `detached: true` makes the child its OWN process-group leader (pgid === pid) so
 22	// a timeout can kill the WHOLE tree, not just the direct child. This is a
 23	// correctness fix, not hygiene: in the 2026-06-12 I Love Coding run a turn ran
 24	// past the cap, SIGTERM hit only the direct child, and a leaked worker kept the
 25	// stdout pipe open — so `close` never fired and the whole debate hung ~45 min at
 26	// ~0 CPU. Group-kill closes the pipe, `close` fires, the turn resolves as timeout,
 27	// and the round proceeds. (Negative pid in process.kill = signal the group.)
 28	function runCli(cmd: string, args: string[], cwd: string, timeoutMs: number): Promise<CliCapture> {
 29	  return new Promise((resolve) => {
 30	    const child = spawn(cmd, args, { cwd, stdio: ["ignore", "pipe", "pipe"], detached: true });
 31	    let stdout = "";
 32	    let stderr = "";
 33	    let timedOut = false;
 34	    let hardTimer: ReturnType<typeof setTimeout> | undefined;
 35	
 36	    // Signal the child's whole process group. ESRCH (group already gone) is benign.
 37	    // We target the group (-pid), never node's own group, because `detached` put
 38	    // the child in its own group — so this can't kill the orchestrator.
 39	    const killGroup = (signal: NodeJS.Signals) => {
 40	      try { if (child.pid) process.kill(-child.pid, signal); }
 41	      catch { /* already dead */ }
 42	    };
 43	
 44	    const timer = setTimeout(() => {
 45	      timedOut = true;
 46	      killGroup("SIGTERM");
 47	      hardTimer = setTimeout(() => killGroup("SIGKILL"), KILL_GRACE_MS); // escalate if ignored
 48	    }, timeoutMs);
 49	
 50	    const finish = (cap: CliCapture) => {
 51	      clearTimeout(timer);
 52	      if (hardTimer) clearTimeout(hardTimer);
 53	      resolve(cap);
 54	    };
 55	
 56	    child.stdout.on("data", (d) => { stdout += d.toString(); });
 57	    child.stderr.on("data", (d) => { stderr += d.toString(); });
 58	    child.on("error", (e) => { finish({ code: null, stdout, stderr: String(e), timedOut }); });
 59	    child.on("close", (code) => { finish({ code, stdout, stderr, timedOut }); });
 60	  });
 61	}
 62	
 63	export type AgentResult =
 64	  | { ok: true; text: string; costUsd?: number; raw?: CliCapture }
 65	  | { ok: false; error: string; budgetExhausted?: true; raw?: CliCapture };
 66	
 67	export type Participant = {
 68	  id: string;
 69	  display: string;
 70	  vendor: string; // used for the cross-vendor sanity check (diversity is the whole point)
 71	  run: (prompt: string, cwd: string) => Promise<AgentResult>;
 72	};
 73	
 74	// exit 126/127 = the shell could not run the binary at all (e.g. a stale asdf
 75	// shim shadowing the real install) — a setup problem, not an agent failure.
 76	function spawnFailure(r: CliCapture): string | null {
 77	  if (r.code === 126 || r.code === 127) {
 78	    return `binary not runnable (exit ${r.code}) — check PATH / asdf shims, or set 'bin' in debate.yaml. stderr: ${r.stderr.slice(0, 200)}`;
 79	  }
 80	  return null;
 81	}
 82	
 83	// --- Claude Code: rich JSON envelope -------------------------------------------------
 84	export type ClaudeOpts = { maxBudgetUsd?: number; timeoutMs?: number; effort?: string };
 85	
 86	export function claudeAdapter(model = "sonnet", opts: ClaudeOpts = {}): Participant {
 87	  // $5 default: raised from $2 after the redactio (full transcript + repo traversal at
 88	  // effort:high) hit the $2 cap on a real medium-sized run. Use --budget to override.
 89	  const budget = opts.maxBudgetUsd ?? 5;
 90	  const timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
 91	  return {
 92	    id: "claude",
 93	    display: `Claude (${model})`,
 94	    vendor: "anthropic",
 95	    async run(prompt, cwd) {
 96	      const r = await runCli("claude", [
 97	        "-p", prompt,
 98	        "--output-format", "json",
 99	        "--model", model,
100	        // read-only evidence tools; enough to run the existing tests = the moat.
101	        // Comma-separated permission rules (research/claude-code-headless.md) —
102	        // the rules themselves contain spaces, so commas are the only safe separator.
103	        "--allowedTools", "Read,Glob,Grep,WebFetch,WebSearch,Bash(npm test *),Bash(pytest *),Bash(bun test *),Bash(rspec *),Bash(bundle exec rspec *),Bash(ls *),Bash(cat *),Bash(git diff *),Bash(git log *)",
104	        "--disallowedTools", "Edit,Write,NotebookEdit",
105	        "--permission-mode", "dontAsk", // headless: deny anything not allowlisted, never prompt
106	        "--no-session-persistence",
107	        "--max-budget-usd", String(budget),
108	        // Reasoning effort, to dose token spend. Native flag; values: low|medium|high|xhigh|max.
109	        ...(opts.effort ? ["--effort", opts.effort] : []),
110	      ], cwd, timeoutMs);
111	      if (r.timedOut) return { ok: false, error: "timeout", raw: r };
112	      const spawnErr = spawnFailure(r);
113	      if (spawnErr) return { ok: false, error: spawnErr, raw: r };
114	      try {
115	        const j = JSON.parse(r.stdout);
116	        // CANARY LESSON: trust is_error, NOT subtype. On error, subtype stays "success"
117	        // while is_error flips true. So classify on is_error + exit code.
118	        if (r.code === 0 && j.is_error === false) {
119	          return { ok: true, text: String(j.result ?? ""), costUsd: j.total_cost_usd, raw: r };
120	        }
121	        // CANARY LESSON (2026-06-11): on budget exhaustion there is NO `result`
122	        // string — the message lives in the `errors` array and subtype becomes
123	        // "error_max_budget_usd". Read all three places, most specific first.
124	        // Note: for SUCCESS we trust is_error not subtype (subtype lies); but for
125	        // budget exhaustion specifically, subtype IS the reliable discriminator.
126	        const budgetExhausted: true | undefined = j.subtype === "error_max_budget_usd" ? true : undefined;
127	        const error =
128	          Array.isArray(j.errors) && j.errors.length > 0 ? j.errors.join("; ")
129	          : typeof j.result === "string" && j.result ? j.result
130	          : `is_error=${j.is_error} subtype=${j.subtype}`;
131	        return { ok: false, error, ...(budgetExhausted && { budgetExhausted }), raw: r };
132	      } catch {
133	        return { ok: false, error: `exit=${r.code} ${r.stderr.slice(0, 200)}`, raw: r };
134	      }
135	    },
136	  };
137	}
