  2	
  3	import { test } from "node:test";
  4	import assert from "node:assert/strict";
  5	import { readFile } from "node:fs/promises";
  6	import { join, dirname } from "node:path";
  7	import { fileURLToPath } from "node:url";
  8	import { parseDebateConfig, serializeDebateConfig } from "../src/config.ts";
  9	
 10	const here = dirname(fileURLToPath(import.meta.url));
 11	
 12	test("parses the shipped example config (a portable template — no host-specific bin)", async () => {
 13	  const text = await readFile(join(here, "..", "examples", "debate.yaml"), "utf8");
 14	  const cfg = parseDebateConfig(text);
 15	  assert.equal(cfg.rounds, 1);
 16	  assert.equal(cfg.timeoutMinutes, 10);
 17	  assert.equal(cfg.repo, undefined); // commented out
 18	  assert.equal(cfg.participants?.length, 2);
 19	  assert.deepEqual(cfg.participants?.[0], { adapter: "claude", model: "sonnet", maxBudgetUsd: 2 });
 20	  assert.equal(cfg.participants?.[1].adapter, "codex");
 21	  // P2 fix: the template stays portable — the host-specific bin is commented out so
 22	  // copying it never assumes /opt/homebrew. `--init` pins a real bin per machine.
 23	  assert.equal(cfg.participants?.[1].bin, undefined);
 24	  // The judge (respondeo) is Opus — distinct model from the Sonnet debater, so no
 25	  // exact-display correlated-error match (decision #5).
 26	  assert.equal(cfg.judge?.adapter, "claude");
 27	  assert.equal(cfg.judge?.model, "opus");
 28	});
 29	
 30	test("serializeDebateConfig round-trips through parseDebateConfig", () => {
 31	  const cfg = {
 32	    rounds: 2,
 33	    timeoutMinutes: 10,
 34	    participants: [
 35	      { adapter: "claude" as const, model: "sonnet", maxBudgetUsd: 2 },
 36	      { adapter: "codex" as const, bin: "/opt/homebrew/bin/codex", effort: "medium" },
 37	      { adapter: "agy" as const, model: "Gemini 3.5 Flash (High)" },
 38	    ],
 39	    judge: { adapter: "claude" as const, model: "opus", effort: "high", maxBudgetUsd: 2 },
 40	  };
 41	  assert.deepEqual(parseDebateConfig(serializeDebateConfig(cfg)), cfg);
 42	});
 43	
 44	test("serializeDebateConfig quotes edge-whitespace values, leaves spaces/parens bare", () => {
 45	  const cfg = {
 46	    participants: [
 47	      { adapter: "codex" as const, model: " spaced " },               // quoted to preserve edges
 48	      { adapter: "claude" as const, model: "Gemini 3.5 Flash (High)" }, // stays bare
 49	    ],
 50	  };
 51	  const text = serializeDebateConfig(cfg);
