 60	    /comment marker/,
 61	  );
 62	});
 63	
 64	test("parses a judge: block (respondeo)", () => {
 65	  const cfg = parseDebateConfig(
 66	    "participants:\n  - adapter: claude\n  - adapter: codex\njudge:\n  adapter: claude\n  model: opus\n  effort: low\n",
 67	  );
 68	  assert.deepEqual(cfg.judge, { adapter: "claude", model: "opus", effort: "low" });
 69	  assert.equal(cfg.participants?.length, 2); // judge is separate from the debaters
 70	});
 71	
 72	test("judge is undefined when the section is absent", () => {
 73	  const cfg = parseDebateConfig("participants:\n  - adapter: claude\n  - adapter: codex\n");
 74	  assert.equal(cfg.judge, undefined);
 75	});
 76	
 77	test("rejects an unknown judge key with the line number", () => {
 78	  assert.throws(
 79	    () => parseDebateConfig("judge:\n  adapter: claude\n  budget: 2\n"),
 80	    /line 3: unknown participant key "budget"/,
 81	  );
 82	});
 83	
 84	test("rejects a judge without a valid adapter", () => {
 85	  assert.throws(() => parseDebateConfig("judge:\n  model: opus\n"), /adapter: claude \| agy \| codex/);
 86	});
 87	
 88	test("a top-level key after a judge block closes it (no misattribution)", () => {
 89	  const cfg = parseDebateConfig("judge:\n  adapter: claude\nrounds: 2\n");
 90	  assert.deepEqual(cfg.judge, { adapter: "claude" });
 91	  assert.equal(cfg.rounds, 2);
 92	});
 93	
 94	test("models with spaces and parens survive (agy model names)", () => {
 95	  const cfg = parseDebateConfig(
 96	    "participants:\n  - adapter: agy\n    model: Gemini 3.5 Flash (High)\n  - adapter: claude\n",
 97	  );
 98	  assert.equal(cfg.participants?.[0].model, "Gemini 3.5 Flash (High)");
 99	});
100	
101	test("quoted values are unquoted", () => {
102	  const cfg = parseDebateConfig('repo: "/tmp/my repo"\n');
103	  assert.equal(cfg.repo, "/tmp/my repo");
104	});
105	
106	test("rejects unknown top-level keys with the line number", () => {
107	  assert.throws(() => parseDebateConfig("round: 2\n"), /line 1: unknown key "round"/);
108	});
109	
110	test("parses per-participant effort (free-form string)", () => {
111	  const cfg = parseDebateConfig(
112	    "participants:\n  - adapter: claude\n    effort: high\n  - adapter: codex\n    effort: low\n",
113	  );
114	  assert.equal(cfg.participants?.[0].effort, "high");
115	  assert.equal(cfg.participants?.[1].effort, "low");
116	});
117	
118	test("rejects unknown participant keys", () => {
119	  assert.throws(
120	    () => parseDebateConfig("participants:\n  - adapter: claude\n    budget: 2\n"),
121	    /unknown participant key "budget"/,
122	  );
123	});
124	
125	test("rejects a single-participant lineup", () => {
126	  assert.throws(() => parseDebateConfig("participants:\n  - adapter: claude\n"), /at least 2 participants/);
127	});
128	
129	test("rejects unknown adapters", () => {
130	  assert.throws(
131	    () => parseDebateConfig("participants:\n  - adapter: cursor\n  - adapter: claude\n"),
132	    /adapter: claude \| agy \| codex/,
133	  );
134	});
135	
136	test("rejects non-numeric numeric keys and non-integer rounds", () => {
137	  assert.throws(() => parseDebateConfig("rounds: many\n"), /must be a number/);
138	  assert.throws(() => parseDebateConfig("rounds: 1.5\n"), /non-negative integer/);
139	});
140	
141	test("rejects nested structures it cannot represent", () => {
142	  assert.throws(() => parseDebateConfig("participants:\n  - adapter: claude\n      deep:\n        nope: 1\n"), /line/);
143	});

