108	// --- agy: text-only -------------------------------------------------------------------
109	
110	test("agy: trimmed stdout is the answer", async () => {
111	  process.env.FAKE_STDOUT_FILE = join(fixtures, "claude-success.json"); // any text payload works
112	  const r = await agyAdapter().run("ping", cwd);
113	  assert.equal(r.ok, true);
114	});
115	
116	test("agy: empty stdout → failure even on exit 0", async () => {
117	  const r = await agyAdapter().run("ping", cwd);
118	  assert.equal(r.ok, false);
119	});
120	
121	test("agy: timeout kills the run and reports it", async () => {
122	  process.env.FAKE_SLEEP = "2";
123	  const r = await agyAdapter("Gemini 3.5 Flash (High)", { timeoutMs: 200 }).run("ping", cwd);
124	  assert.equal(r.ok, false);
125	  assert.equal(!r.ok && r.error, "timeout");
126	});
127	
128	test("REGRESSION — leaked worker holding the pipe + SIGTERM-ignoring CLI still times out fast (process-group kill)", async () => {
129	  // Reproduces the deadlock from the 2026-06-12 I Love Coding run: a turn ran past
130	  // the cap, the timeout SIGTERM'd only the direct child, but a leaked worker kept
131	  // stdout open so `close` never fired and the run hung for ~45 min at ~0 CPU.
132	  // The fix (detached spawn + process-GROUP kill) must resolve near the timeout.
133	  process.env.FAKE_HANG = "1";
134	  const start = Date.now();
135	  const r = await agyAdapter("Gemini 3.5 Flash (High)", { timeoutMs: 200 }).run("ping", cwd);

