  1	// Adapter classifier tests — run against fake CLIs (test/fakes/*) that replay
  2	// envelopes captured from REAL runs (research/canary-results.md + the
  3	// 2026-06-11 budget-exceeded canary). The fakes shadow the real binaries via PATH.
  4	
  5	import { test, beforeEach } from "node:test";
  6	import assert from "node:assert/strict";
  7	import { readFileSync } from "node:fs";
  8	import { join, dirname } from "node:path";
  9	import { fileURLToPath } from "node:url";
 10	import { tmpdir } from "node:os";
 11	import { claudeAdapter, agyAdapter, codexAdapter, piAdapter, copilotCliAdapter } from "../src/adapters.ts";
 12	
 13	const here = dirname(fileURLToPath(import.meta.url));
 14	const fixtures = join(here, "fixtures");
 15	process.env.PATH = `${join(here, "fakes")}:${process.env.PATH}`;
 16	
 17	const cwd = tmpdir();
 18	
 19	beforeEach(() => {
 20	  for (const k of Object.keys(process.env)) if (k.startsWith("FAKE_")) delete process.env[k];
 21	});
 22	
 23	// --- claude: JSON envelope ------------------------------------------------------------
 24	
 25	test("claude: success envelope → ok with text and cost", async () => {
 26	  process.env.FAKE_STDOUT_FILE = join(fixtures, "claude-success.json");
 27	  const r = await claudeAdapter().run("ping", cwd);
 28	  assert.equal(r.ok, true);
 29	  assert.equal(r.ok && r.text, "pong");
 30	  assert.equal(r.ok && r.costUsd, 0.10388775);
 31	});
 32	
 33	test("claude: --max-budget-usd defaults to $5, overridable via maxBudgetUsd", async () => {
 34	  const argvFile = join(tmpdir(), `disputatio-claude-argv-${process.pid}.txt`);
 35	  process.env.FAKE_STDOUT_FILE = join(fixtures, "claude-success.json");
 36	  process.env.FAKE_ARGV_FILE = argvFile;
 37	
 38	  await claudeAdapter().run("ping", cwd);
 39	  let argv = readFileSync(argvFile, "utf8").split("\n");
 40	  assert.equal(argv[argv.indexOf("--max-budget-usd") + 1], "5");
 41	
 42	  await claudeAdapter("sonnet", { maxBudgetUsd: 10 }).run("ping", cwd);
 43	  argv = readFileSync(argvFile, "utf8").split("\n");
 44	  assert.equal(argv[argv.indexOf("--max-budget-usd") + 1], "10");
 45	});
 46	
 47	test("claude: effort is passed as --effort when set, omitted when absent", async () => {
 48	  const argvFile = join(tmpdir(), `disputatio-claude-argv-${process.pid}.txt`);
 49	  process.env.FAKE_STDOUT_FILE = join(fixtures, "claude-success.json");
 50	  process.env.FAKE_ARGV_FILE = argvFile;
 51	
 52	  await claudeAdapter("sonnet", { effort: "high" }).run("ping", cwd);
 53	  let argv = readFileSync(argvFile, "utf8").split("\n");
 54	  assert.ok(argv.includes("--effort"), "expected --effort in argv");
 55	  assert.equal(argv[argv.indexOf("--effort") + 1], "high");
 56	
 57	  await claudeAdapter("sonnet").run("ping", cwd);
 58	  argv = readFileSync(argvFile, "utf8").split("\n");
 59	  assert.ok(!argv.includes("--effort"), "expected no --effort when effort is unset");
 60	});
 61	
 62	test("codex: effort is passed as model_reasoning_effort override when set, omitted when absent", async () => {
 63	  const argvFile = join(tmpdir(), `disputatio-codex-argv-${process.pid}.txt`);
 64	  process.env.FAKE_STDOUT_FILE = join(fixtures, "codex-success.jsonl");
 65	  process.env.FAKE_ARGV_FILE = argvFile;
 66	
 67	  await codexAdapter(undefined, { bin: join(here, "fakes", "codex"), effort: "high" }).run("ping", cwd);
 68	  let argv = readFileSync(argvFile, "utf8").split("\n");
 69	  assert.ok(argv.includes(`model_reasoning_effort="high"`), `expected the config override in argv, got ${JSON.stringify(argv)}`);
 70	
 71	  await codexAdapter(undefined, { bin: join(here, "fakes", "codex") }).run("ping", cwd);
 72	  argv = readFileSync(argvFile, "utf8").split("\n");
 73	  assert.ok(!argv.some((a) => a.startsWith("model_reasoning_effort")), "expected no effort override when unset");
 74	});
 75	
 76	test("claude: budget-exceeded envelope (no `result` string) → error from `errors` array", async () => {
 77	  process.env.FAKE_STDOUT_FILE = join(fixtures, "claude-budget-error.json");
 78	  process.env.FAKE_EXIT = "1";
 79	  const r = await claudeAdapter().run("ping", cwd);
 80	  assert.equal(r.ok, false);
 81	  assert.match(!r.ok ? r.error : "", /Reached maximum budget/);
 82	  assert.equal(!r.ok ? r.budgetExhausted : undefined, true); // structural flag, not string-match
 83	});
 84	
 85	test("claude: REGRESSION — subtype lies on error; classify on is_error", async () => {
 86	  process.env.FAKE_STDOUT_FILE = join(fixtures, "claude-model-error.json");
 87	  process.env.FAKE_EXIT = "1";
 88	  const r = await claudeAdapter().run("ping", cwd);
 89	  assert.equal(r.ok, false); // subtype says "success" — is_error must win
 90	  assert.match(!r.ok ? r.error : "", /issue with the selected model/);
 91	});
 92	
 93	test("claude: non-JSON stdout → error with exit code", async () => {
 94	  process.env.FAKE_STDERR = "boom";
 95	  process.env.FAKE_EXIT = "1";
 96	  const r = await claudeAdapter().run("ping", cwd);
 97	  assert.equal(r.ok, false);
 98	  assert.match(!r.ok ? r.error : "", /exit=1/);
 99	});
100	
101	test("claude: exit 126 (stale shim) → setup hint, not a cryptic error", async () => {
102	  process.env.FAKE_EXIT = "126";
103	  const r = await claudeAdapter().run("ping", cwd);
104	  assert.equal(r.ok, false);
105	  assert.match(!r.ok ? r.error : "", /asdf shims/);
106	});
107	
108	// --- agy: text-only -------------------------------------------------------------------
109	
110	test("agy: trimmed stdout is the answer", async () => {
111	  process.env.FAKE_STDOUT_FILE = join(fixtures, "claude-success.json"); // any text payload works
112	  const r = await agyAdapter().run("ping", cwd);
113	  assert.equal(r.ok, true);
114	});
