 83	// --- Claude Code: rich JSON envelope -------------------------------------------------
 84	export type ClaudeOpts = { maxBudgetUsd?: number; timeoutMs?: number; effort?: string };
 85	
 86	export function claudeAdapter(model = "sonnet", opts: ClaudeOpts = {}): Participant {
 87	  // $5 default: raised from $2 after the redactio (full transcript + repo traversal at
 88	  // effort:high) hit the $2 cap on a real medium-sized run. Use --budget to override.
 89	  const budget = opts.maxBudgetUsd ?? 5;
 90	  const timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
 91	  return {
 92	    id: "claude",
 93	    display: `Claude (${model})`,
 94	    vendor: "anthropic",
 95	    async run(prompt, cwd) {
 96	      const r = await runCli("claude", [
 97	        "-p", prompt,
 98	        "--output-format", "json",
 99	        "--model", model,
100	        // read-only evidence tools; enough to run the existing tests = the moat.
101	        // Comma-separated permission rules (research/claude-code-headless.md) —
102	        // the rules themselves contain spaces, so commas are the only safe separator.
103	        "--allowedTools", "Read,Glob,Grep,WebFetch,WebSearch,Bash(npm test *),Bash(pytest *),Bash(bun test *),Bash(rspec *),Bash(bundle exec rspec *),Bash(ls *),Bash(cat *),Bash(git diff *),Bash(git log *)",
104	        "--disallowedTools", "Edit,Write,NotebookEdit",
105	        "--permission-mode", "dontAsk", // headless: deny anything not allowlisted, never prompt
106	        "--no-session-persistence",
107	        "--max-budget-usd", String(budget),
108	        // Reasoning effort, to dose token spend. Native flag; values: low|medium|high|xhigh|max.
109	        ...(opts.effort ? ["--effort", opts.effort] : []),
110	      ], cwd, timeoutMs);
111	      if (r.timedOut) return { ok: false, error: "timeout", raw: r };
112	      const spawnErr = spawnFailure(r);
113	      if (spawnErr) return { ok: false, error: spawnErr, raw: r };
114	      try {
115	        const j = JSON.parse(r.stdout);
116	        // CANARY LESSON: trust is_error, NOT subtype. On error, subtype stays "success"
117	        // while is_error flips true. So classify on is_error + exit code.
118	        if (r.code === 0 && j.is_error === false) {
119	          return { ok: true, text: String(j.result ?? ""), costUsd: j.total_cost_usd, raw: r };
120	        }
121	        // CANARY LESSON (2026-06-11): on budget exhaustion there is NO `result`
122	        // string — the message lives in the `errors` array and subtype becomes
123	        // "error_max_budget_usd". Read all three places, most specific first.
124	        // Note: for SUCCESS we trust is_error not subtype (subtype lies); but for
125	        // budget exhaustion specifically, subtype IS the reliable discriminator.
126	        const budgetExhausted: true | undefined = j.subtype === "error_max_budget_usd" ? true : undefined;
127	        const error =
128	          Array.isArray(j.errors) && j.errors.length > 0 ? j.errors.join("; ")
129	          : typeof j.result === "string" && j.result ? j.result
130	          : `is_error=${j.is_error} subtype=${j.subtype}`;
131	        return { ok: false, error, ...(budgetExhausted && { budgetExhausted }), raw: r };
132	      } catch {
133	        return { ok: false, error: `exit=${r.code} ${r.stderr.slice(0, 200)}`, raw: r };
134	      }
135	    },
136	  };
137	}
