 1	// Build/distribution guard. A real `npm install -g disputatio@0.2.0` crashed because the
 2	// bin was a `.ts` file — Node refuses to type-strip TypeScript under node_modules. The fix
 3	// ships a bundled `.js` bin. Then a SECOND bug: a shebang in src + a `--banner:js` shebang
 4	// produced TWO `#!` lines, and the line-2 one is a syntax error. This test guards both:
 5	// the published bin must be runnable JS with exactly one shebang, on line 1.
 6	//
 7	// Depends on esbuild (a devDependency), so it SKIPS on a zero-dep clone (`node --test`
 8	// without `npm install`) and runs once dependencies are installed.
 9	
10	import { test } from "node:test";
11	import assert from "node:assert/strict";
12	import { execFile } from "node:child_process";
13	import { promisify } from "node:util";
14	import { readFile, access } from "node:fs/promises";
15	import { join, dirname } from "node:path";
16	import { fileURLToPath } from "node:url";
17	
18	const execFileAsync = promisify(execFile);
19	const root = join(dirname(fileURLToPath(import.meta.url)), "..");
20	
21	const esbuildPresent = await access(join(root, "node_modules/.bin/esbuild")).then(() => true, () => false);
22	
23	test(
24	  "published bundle: JS bin with a single line-1 shebang that runs",
25	  { skip: esbuildPresent ? false : "esbuild not installed (zero-dep clone)" },
26	  async () => {
27	    await execFileAsync("npm", ["run", "build"], { cwd: root });
28	    const dist = join(root, "dist", "index.js");
29	    const lines = (await readFile(dist, "utf8")).split("\n");
30	    assert.equal(lines[0], "#!/usr/bin/env node", "line 1 must be the shebang");
31	    assert.ok(!lines.slice(1).some((l) => l.startsWith("#!")), "no second shebang (the double-shebang regression)");
32	    // The bin must actually load + run (the bundle, end to end). --help exits 0 to stderr.
33	    const r = await execFileAsync("node", [dist, "--help"]).catch((e: { stdout?: string; stderr?: string }) => e);
34	    assert.match((r.stderr ?? "") + (r.stdout ?? ""), /usage: disputatio/);
35	  },
36	);

